// MembershipRetrievalHooks declares complete-model read callbacks. Reference a local factory with retrieval=Factory on the model directive. The stored model is a read-only value; getters remain explicit.
type MembershipRetrievalHooks struct {
	// Retrieved runs after successful stored hydration and row closure. The executor retains the caller's capability and wrappers; no write transaction is created implicitly. Return an error to stop this read. Nil is skipped.
	Retrieved func(context.Context, database.Executor, Membership) error
}

// MembershipRetrievalObserver retains this model's concrete retrieval factory type. Names share the selected database's write/retrieval namespace.
type MembershipRetrievalObserver = lifecycle.Observer[Membership, MembershipRetrievalHooks]

// NewMembershipRetrievalObserver declares a typed retrieval observer without registering or constructing hooks.
func NewMembershipRetrievalObserver(observer string) MembershipRetrievalObserver {
	return lifecycle.NewRetrievalObserver[Membership, MembershipRetrievalHooks](observer)
}

// RegisterMembershipRetrievalObserver binds dependency construction to a database module. Its factory runs once per nonempty complete fetch/batch and selected model role; write hydration, DTOs and scalar reads skip it.
func RegisterMembershipRetrievalObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer MembershipRetrievalObserver, construct func(foundation.Resolver) (func() MembershipRetrievalHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (MembershipRetrievalHooks) foundryRetrievalHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.RetrievalHooks[Membership], error) {
	factories, err := lifecycle.RetrievalObserverFactories[Membership, MembershipRetrievalHooks](observerSet)
	if err != nil {
		return foundryquery.RetrievalHooks[Membership]{}, err
	}
	var allHooks []MembershipRetrievalHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Membership]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.RetrievalHooks[Membership]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Membership]{}, err
	}
	return foundryquery.RetrievalHooks[Membership]{Retrieved: func(ctx context.Context, executor database.Executor, item Membership) error {
		for _, hooks := range allHooks {
			if err := ctx.Err(); err != nil {
				return err
			}
			if hooks.Retrieved != nil {
				if err := hooks.Retrieved(ctx, executor, item); err != nil {
					return err
				}
			}
		}
		return ctx.Err()
	}}, nil
}

// MembershipAuditPolicy selects stored fields for auditing. Zero applies automatic sensitive-name redaction.
// Exclusion/redaction cannot hide the primary key while retaining it as the subject identity; that policy fails capture.
type MembershipAuditPolicy struct {
	_ [0]*Membership
	// ID controls the audit representation of stored read_memberships.id.
	ID record.Disclosure
	// TenantID controls the audit representation of stored read_memberships.tenant_id.
	TenantID record.Disclosure
	// MemberID controls the audit representation of stored read_memberships.member_id.
	MemberID record.Disclosure
	// GroupID controls the audit representation of stored read_memberships.group_id.
	GroupID record.Disclosure
}

// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Updates, soft deletes and restorations record assigned or changed fields plus the key; create and delete record every field.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes MembershipChanges) Audit(policy MembershipAuditPolicy) (record.Model[Membership, int64], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Membership, int64]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Membership, int64]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Membership, int64]{}, err
	}
	if err = record.Capture(builder, "id", codec.Signed[int64](), changes.fields.ID, policy.ID); err != nil {
		return record.Model[Membership, int64]{}, err
	}
	if err = record.Capture(builder, "tenant_id", codec.Signed[int64](), changes.fields.TenantID, policy.TenantID); err != nil {
		return record.Model[Membership, int64]{}, err
	}
	if err = record.Capture(builder, "member_id", codec.Signed[int64](), changes.fields.MemberID, policy.MemberID); err != nil {
		return record.Model[Membership, int64]{}, err
	}
	if err = record.Capture(builder, "group_id", codec.Signed[int64](), changes.fields.GroupID, policy.GroupID); err != nil {
		return record.Model[Membership, int64]{}, err
	}
	return builder.Build()
}

